```tsx
import "./TimeList.css";

export type TimeState = "past" | "next" | "later";

export interface TimeItem {
  id: string;
  name: string;
  /** Display time, for example "13:14". */
  time: string;
  state: TimeState;
}

export interface TimeListProps {
  items: readonly TimeItem[];
  /** Accessible name for the list. */
  label?: string;
  onSelect?: (item: TimeItem) => void;
}

const STATE_TEXT: Record<TimeState, string> = {
  past: "passed",
  next: "next",
  later: "later",
};

export function TimeList({ items, label = "Today", onSelect }: TimeListProps) {
  return (
    <ol className="time-list" aria-label={label}>
      {items.map((item) => (
        <li key={item.id} className={`time-list__item is-${item.state}`}>
          <button
            type="button"
            className="time-list__button"
            aria-current={item.state === "next" ? "time" : undefined}
            onClick={() => onSelect?.(item)}
          >
            <span className="time-list__name">{item.name}</span>
            {item.state === "next" && (
              <span className="time-list__tag" aria-hidden="true">
                Next
              </span>
            )}
            <span className="time-list__time">{item.time}</span>
            <span className="time-list__state">, {STATE_TEXT[item.state]}</span>
          </button>
        </li>
      ))}
    </ol>
  );
}
```

```css
.time-list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--hair);
  color: var(--ink);
  font: inherit;
}

.time-list__item {
  border-bottom: 1px solid var(--hair);
}

.time-list__button {
  position: relative;
  display: flex;
  align-items: baseline;
  gap: 0.75em;
  width: 100%;
  margin: 0;
  padding: 0.9em 0.75em;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: clamp(1rem, 0.9rem + 0.4vw, 1.375rem);
  text-align: start;
  cursor: pointer;
  transition: background-color 200ms ease;
}

.time-list__button:hover {
  background: var(--myelin-wash);
}

.time-list__name {
  flex: 1 1 auto;
  min-width: 0;
}

.time-list__time {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* Past: quieter text. Muted text is not used on the wash, so hover lifts it to ink. */
.time-list__item.is-past .time-list__button {
  color: var(--muted);
}

.time-list__item.is-past .time-list__button:hover {
  color: var(--ink);
}

/* Later: plain ink, the default. */
.time-list__item.is-later .time-list__button {
  color: var(--ink);
}

/* Next: highlighted with the cresyl wash and a marker bar. */
.time-list__item.is-next .time-list__button {
  background: var(--cresyl-wash);
  box-shadow: inset 0.25em 0 0 var(--cresyl);
  color: var(--ink);
  font-weight: 600;
}

.time-list__item.is-next .time-list__button:hover {
  background: var(--cresyl-wash);
}

.time-list__tag {
  color: var(--cresyl);
  font-size: 0.7em;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
}

/* Spoken state for screen readers; visually hidden without display: none. */
.time-list__state {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

:root[data-motion="reduce"] .time-list__button {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .time-list__button {
    transition: none;
  }
}
